package com.servicedesk360.service;
import com.servicedesk360.dto.common.PageResponse; import com.servicedesk360.dto.tenant.*; import com.servicedesk360.entity.*; import com.servicedesk360.exception.*; import com.servicedesk360.repository.*; import org.springframework.data.domain.*; import org.springframework.stereotype.Service; import org.springframework.transaction.annotation.Transactional;
@Service public class TeamQueueService{private final TeamRepository teams;private final QueueRepository queues;private final CategoryRepository categories;private final CurrentUserService current;public TeamQueueService(TeamRepository t,QueueRepository q,CategoryRepository c,CurrentUserService u){teams=t;queues=q;categories=c;current=u;}private CurrentUserService.CurrentUser admin(){var me=current.getRequiredUser();if(me.role()!=Role.TENANT_ADMIN)throw new UnauthorizedException("Tenant administrator role required");return me;}@Transactional(readOnly=true)public PageResponse<TeamResponse> listTeams(Pageable p){var me=admin();return PageResponse.from(teams.findAllByTenantId(me.tenantId(),p).map(TeamResponse::from));}@Transactional public TeamResponse createTeam(TeamRequest r){var me=admin();if(teams.existsByTenantIdAndName(me.tenantId(),r.name().trim()))throw new BusinessException("TEAM_EXISTS","Team name already exists");return TeamResponse.from(teams.save(new Team(me.tenantId(),r.name().trim(),r.description())));}@Transactional(readOnly=true)public PageResponse<QueueResponse> listQueues(Pageable p){var me=admin();return PageResponse.from(queues.findAllByTenantId(me.tenantId(),p).map(QueueResponse::from));}@Transactional public QueueResponse createQueue(QueueRequest r){var me=admin();var team=teams.findByIdAndTenantId(r.teamId(),me.tenantId()).orElseThrow(()->new ResourceNotFoundException("Team not found"));if(queues.existsByTenantIdAndName(me.tenantId(),r.name().trim()))throw new BusinessException("QUEUE_EXISTS","Queue name already exists");return QueueResponse.from(queues.save(new Queue(me.tenantId(),team,r.name().trim(),r.description())));}@Transactional(readOnly=true)public PageResponse<CategoryResponse> listCategories(Pageable p){var me=admin();return PageResponse.from(categories.findAllByTenantId(me.tenantId(),p).map(CategoryResponse::from));}@Transactional public CategoryResponse createCategory(CategoryRequest r){var me=admin();if(categories.existsByTenantIdAndName(me.tenantId(),r.name().trim()))throw new BusinessException("CATEGORY_EXISTS","Category name already exists");return CategoryResponse.from(categories.save(new Category(me.tenantId(),r.name().trim(),r.description())));}}
